function addEntry(compilation, context, name, entry) {
	return new Promise((resolve, reject) => {
		const dep = DynamicEntryPlugin.createDependency(entry, name);
		compilation.addEntry(context, dep, name, err => {
			if (err) return reject(err);
			resolve();
		});
	});
}

compiler.plugin("make", function(compilation, done) {
		invalidator.startBuilding();
		const allEntries = Object.keys(compilerEntryInfo).map(page => {
			const { name, entry } = compilerEntryInfo[page];
			compilerEntryInfo[page].status = BUILDING;
			return addEntry(compilation, process.cwd(), name, entry);
		});

		Promise.all(allEntries)
			.then(() => done())
			.catch(done);
	});

	compiler.plugin("done", function() {
		// Call all the doneCallbacks
		Object.keys(compilerEntryInfo).forEach(page => {
			const entryInfo = compilerEntryInfo[page];
			if (entryInfo.status !== BUILDING) return;
			entryInfo.status = BUILT;
			compilerEntryInfo[page].lastActiveTime = Date.now();
			doneCallbacks.emit(page);
		});

		invalidator.doneBuilding();
	});
```
